"""Held-out answer keys and the readout-quality metric for
llm-activation-readout-lens.

Host-side only: this directory is never bind-mounted into the agent's container,
and the rendered Harbor bundle carries it under ``tests/meta/``.  The evaluation
container holds the evaluation INPUTS (token ids + read-out position) but never
the intermediates (answers), and the lens's editable ``transport`` never receives
an input or item id at all.  ``build_eval.py`` (beside this file) generates both
halves from the jlens lens-eval sets.

``parser.py`` imports this, decodes the harness's per-(item, layer) top-K token
ids, and scores them here -- so scoring never shares a process with the code
being scored.

Metric (the jlens paper's "Quantitative Methodological Comparisons"): an
intermediate is recovered at k if any of its single-token forms is among the
lens's top-k tokens at ANY layer; pass@k = mean over items of the fraction of the
item's intermediates recovered at k.  The per-set summary is the paper's
"normalized pass@k AUC": the area under pass@k plotted against log k for
k = 1 .. K (K = 100, the harness's read-out depth), normalized so a lens that
always ranks every intermediate first scores 1.  pass@1/5/10 are diagnostics.
Every item of every set is scored; a missing or malformed row counts as a miss.
"""
from __future__ import annotations

import json
import math
from functools import lru_cache
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
KMAX = 100


def _answers_path(setting: str) -> Path:
    return _HERE / f"answers_{setting}.json"


def known(setting: str) -> bool:
    return _answers_path(setting).exists()


@lru_cache(maxsize=None)
def _load(setting: str) -> dict:
    return json.loads(_answers_path(setting).read_text(encoding="utf-8"))


def sets(setting: str) -> list[str]:
    return list(_load(setting)["sets"]) if known(setting) else []


def expected(setting: str) -> dict:
    """{set: (n_items, inputs_sha256)} the run must report having evaluated."""
    return {name: (int(s["n_items"]), s["inputs_sha256"])
            for name, s in _load(setting)["sets"].items()}


def _best_ranks(preds: np.ndarray, cand_sets: list) -> list[int]:
    """preds: [n_layers, K] top-K ids for one item; returns, per intermediate, its
    best (min over layers and candidate forms) 1-based rank, or KMAX+1 if absent."""
    K = preds.shape[1]
    out = []
    for cands in cand_sets:
        best = KMAX + 1
        for c in cands:
            hit = np.nonzero(preds == c)
            if hit[1].size:
                best = min(best, int(hit[1].min()) + 1)
        out.append(best if best <= min(K, KMAX) else KMAX + 1)
    return out


def score_set(preds: np.ndarray, setting: str, name: str) -> dict:
    """Score one evaluation set.  preds: int32 [n_items, n_layers, K]."""
    items = _load(setting)["sets"][name]["items"]
    preds = np.asarray(preds)
    if preds.ndim != 3 or preds.shape[0] != len(items):
        raise ValueError(f"{name}: preds shape {preds.shape} does not match {len(items)} items")
    if preds.shape[2] < KMAX:
        raise ValueError(f"{name}: read-out depth {preds.shape[2]} < {KMAX}")
    ranks = [_best_ranks(preds[i], it["cand_ids"]) for i, it in enumerate(items)]
    pk = {}
    for k in range(1, KMAX + 1):
        pk[k] = float(np.mean([np.mean([r <= k for r in rs]) for rs in ranks]))
    auc = sum(pk[k] * math.log((k + 1) / k) for k in range(1, KMAX)) / math.log(KMAX)
    return {"auc": auc, "p1": pk[1], "p5": pk[5], "p10": pk[10], "n": len(items)}


def score(preds_by_set: dict, setting: str) -> dict:
    if not known(setting):
        raise ValueError(f"unknown setting {setting!r}")
    missing = [s for s in sets(setting) if s not in preds_by_set]
    if missing:
        raise ValueError(f"{setting}: no predictions for {missing}")
    return {name: score_set(preds_by_set[name], setting, name) for name in sets(setting)}

