"""Output parser for llm-activation-readout-lens (predict-then-score).

The run script relays, after every python process has exited:

    MLSB_RUN_TOKEN=<nonce>                       (first)
    FINAL_PRED[<nonce>]: <zlib+base64 of preds.npz FILE>
    FINAL_META[<nonce>]: {"sets": {set: {"n":..,"sha256":..}}, "fit_s":.., "fit_ok":..}

The predictions are the lens's top-K token ids per (item, layer) for every
evaluation set of the setting.  The answers live host-side in
holdout/llm-activation-readout-lens/, so the readout quality is computed in a
process that neither ran the submission nor was reachable by it.  Emitting
exactly one marker of each kind (checked here) means a shutdown hook or a
rewritten run script cannot append a forged value -- and since the answers are
unreachable, a forged prediction could not raise the score anyway.

Scored columns per setting <label> and evaluation set <set>:
  auc_<set>_<label>   normalized pass@k AUC over log k, k = 1..100, in percent
                      (the jlens paper's summary metric); higher is better
  p10_<set>_<label>   pass@10 in percent (diagnostic)
  fit_s_<label>       lens fit wall-time in seconds (diagnostic)
"""
from __future__ import annotations

import base64
import io
import json
import re
import sys
import zlib
from pathlib import Path

import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
# Only reach for the repo checkout when mlsbench is genuinely absent.
# Under Harbor this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/,
# so a __file__-derived PROJECT_ROOT is /tmp and this would put an
# agent-writable directory at the front of the verifier's sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(PROJECT_ROOT / "src"))

from mlsbench.agent.parsers import OutputParser, ParseResult  # noqa: E402
from mlsbench.holdout import load_holdout_module  # noqa: E402

# Native layout: <repo>/holdout/<task>/dgp.py.  Harbor layout: score_task.py
# loads this parser from a private copy of tests/meta/ with dgp.py alongside.
_HERE = Path(__file__).resolve().parent

dgp = load_holdout_module("llm-activation-readout-lens", __file__)  # noqa: E402

_TOKEN_RE = re.compile(r"^MLSB_RUN_TOKEN=([0-9a-f]{8,64})$")


class Parser(OutputParser):
    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        feedback: list[str] = []
        metrics: dict[str, float] = {}
        lines = [ln.strip() for ln in raw_output.splitlines()]

        for ln in lines:
            if ln.startswith("RUN_INFO:") or ln.startswith("RUN_ERROR:"):
                feedback.append(ln)
        feedback = feedback[-12:]

        token = None
        for ln in lines:
            m = _TOKEN_RE.match(ln)
            if m:
                token = m.group(1)
                break
        if token is None:
            feedback.append(f"No run token for {cmd_label}; the run script did not start.")
            return ParseResult(feedback="\n".join(feedback), metrics={})

        pred_re = re.compile(r"^FINAL_PRED\[" + re.escape(token) + r"\]:\s*(\S+)$")
        meta_re = re.compile(r"^FINAL_META\[" + re.escape(token) + r"\]:\s*(.*)$")
        payload = meta = None
        n_pred = n_meta = 0
        for ln in lines:
            m = pred_re.match(ln)
            if m:
                payload = m.group(1)
                n_pred += 1
            m = meta_re.match(ln)
            if m:
                meta = m.group(1).strip()
                n_meta += 1

        # Exactly one of each; taking the last of several would let anything able
        # to append a line overwrite the honest value.
        if n_pred > 1 or n_meta > 1:
            feedback.append(
                f"Run {cmd_label} emitted {n_pred} prediction and {n_meta} meta "
                "markers; exactly one of each is expected, so nothing is scored."
            )
            return ParseResult(feedback="\n".join(feedback), metrics={})
        if meta is None:
            feedback.append(f"No FINAL_META marker for {cmd_label}; run did not complete.")
            return ParseResult(feedback="\n".join(feedback), metrics={})
        if meta.upper().startswith("INVALID"):
            feedback.append(f"Run {cmd_label} produced no valid result ({meta}).")
            return ParseResult(feedback="\n".join(feedback), metrics={})

        try:
            fields = json.loads(meta)
            reported = {k: (int(v["n"]), str(v["sha256"])) for k, v in fields["sets"].items()}
        except Exception as exc:  # noqa: BLE001
            feedback.append(f"Run {cmd_label} relayed unreadable metadata ({type(exc).__name__}).")
            return ParseResult(feedback="\n".join(feedback), metrics={})
        if not dgp.known(cmd_label):
            feedback.append(f"Unknown evaluation setting {cmd_label}; not scored.")
            return ParseResult(feedback="\n".join(feedback), metrics={})

        # Fail CLOSED: the run must report evaluating exactly the input arrays the
        # held-out labels belong to, set by set.
        exp = dgp.expected(cmd_label)
        if reported != exp:
            feedback.append(
                f"Run {cmd_label} did not report evaluating the input arrays the labels "
                "belong to; not scored."
            )
            return ParseResult(feedback="\n".join(feedback), metrics={})

        if payload is None:
            feedback.append(f"No predictions for {cmd_label}; not scored.")
            return ParseResult(feedback="\n".join(feedback), metrics={})
        try:
            with np.load(
                io.BytesIO(zlib.decompress(base64.b64decode(payload))),
                allow_pickle=False,
            ) as z:
                preds = {k: np.asarray(z[k]) for k in z.files}
        except Exception as exc:  # noqa: BLE001
            feedback.append(
                f"Could not decode predictions for {cmd_label} ({type(exc).__name__}); not scored."
            )
            return ParseResult(feedback="\n".join(feedback), metrics={})

        try:
            res = dgp.score(preds, cmd_label)
        except Exception as exc:  # noqa: BLE001
            feedback.append(f"Scoring {cmd_label} failed: {exc}")
            return ParseResult(feedback="\n".join(feedback), metrics={})

        for name, r in res.items():
            metrics[f"auc_{name}_{cmd_label}"] = 100.0 * r["auc"]
            metrics[f"p10_{name}_{cmd_label}"] = 100.0 * r["p10"]
            feedback.append(
                f"{cmd_label}/{name}: pass@k-AUC={100.0 * r['auc']:.2f} "
                f"pass@1={100.0 * r['p1']:.1f} pass@10={100.0 * r['p10']:.1f} (n={r['n']})"
            )
        try:
            fit_s = float(fields.get("fit_s", float("nan")))
            if fit_s == fit_s:  # not NaN
                metrics[f"fit_s_{cmd_label}"] = fit_s
        except (TypeError, ValueError):
            pass
        return ParseResult(feedback="\n".join(feedback), metrics=metrics)
